WITH overlapping_pages AS ( SELECT cp1.cp_catalog_page_sk AS page_sk_1, cp1.cp_catalog_page_id AS page_id_1, cp1.cp_department AS dept_1, cp2.cp_catalog_page_sk AS page_sk_2, cp2.cp_catalog_page_id AS page_id_2, cp2.cp_department AS dept_2, GREATEST(cp1.cp_start_date_sk, cp2.cp_start_date_sk) AS overlap_start_sk, LEAST(cp1.cp_end_date_sk, cp2.cp_end_date_sk) AS overlap_end_sk FROM catalog_page cp1 INNER JOIN catalog_page cp2 ON cp1.cp_catalog_page_sk < cp2.cp_catalog_page_sk AND cp1.cp_start_date_sk <= cp2.cp_end_date_sk AND cp1.cp_end_date_sk >= cp2.cp_start_date_sk ), overlap_sales AS ( SELECT op.page_id_1, op.dept_1, op.page_id_2, op.dept_2, op.overlap_start_sk, op.overlap_end_sk, SUM(cs.cs_net_profit) AS total_overlap_profit FROM overlapping_pages op INNER JOIN catalog_sales cs ON cs.cs_catalog_page_sk IN (op.page_sk_1, op.page_sk_2) AND cs.cs_sold_date_sk BETWEEN op.overlap_start_sk AND op.overlap_end_sk GROUP BY op.page_id_1, op.dept_1, op.page_id_2, op.dept_2, op.overlap_start_sk, op.overlap_end_sk ) SELECT page_id_1, dept_1, page_id_2, dept_2, d_start.d_date AS overlap_start_date, d_end.d_date AS overlap_end_date, total_overlap_profit, CASE WHEN total_overlap_profit > 200000 THEN 'Very Profitable' WHEN total_overlap_profit > 100000 THEN 'Profitable' ELSE 'Low' END AS profit_category, RANK() OVER (ORDER BY total_overlap_profit DESC) AS overlap_rank FROM overlap_sales os INNER JOIN date_dim d_start ON os.overlap_start_sk = d_start.d_date_sk INNER JOIN date_dim d_end ON os.overlap_end_sk = d_end.d_date_sk WHERE total_overlap_profit IS NOT NULL ORDER BY overlap_rank LIMIT 10
